"membership_id\") @db.Uuid\n  role         String\n  departmentId String?  @map(\"department_id\") @db.Uuid\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n\n  membership Membership @relation(fields: [tenantId, membershipId], references: [tenantId, id], onDelete: Cascade)\n\n  @@unique([tenantId, membershipId, role, departmentId], map: \"role_grants_scope_key\")\n  @@index([tenantId, membershipId, role, departmentId], map: \"role_grants_scope_idx\")\n  @@index([tenantId])\n  @@index([membershipId])\n  @@map(\"role_grants\")\n}\n\nmodel Session {\n  id               String    @id @default(uuid()) @db.Uuid\n  userId           String    @map(\"user_id\") @db.Uuid\n  kind             String\n  tenantId         String?   @map(\"tenant_id\") @db.Uuid\n  membershipId     String?   @map(\"membership_id\") @db.Uuid\n  activeRole       String?   @map(\"active_role\")\n  expiresAt        DateTime  @map(\"expires_at\")\n  lastUsedAt       DateTime? @map(\"last_used_at\")\n  revokedAt        DateTime? @map(\"revoked_at\")\n  revocationReason String?   @map(\"revocation_reason\")\n  createdAt        DateTime  @default(now()) @map(\"created_at\")\n  updatedAt        DateTime  @updatedAt @map(\"updated_at\")\n\n  user       User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  membership Membership? @relation(fields: [tenantId, membershipId, userId], references: [tenantId, id, userId], onDelete: Restrict)\n  authTokens AuthToken[]\n\n  @@index([userId])\n  @@index([tenantId, membershipId])\n  @@index([expiresAt])\n  @@map(\"sessions\")\n}\n\nmodel AuthToken {\n  id            String    @id @default(uuid()) @db.Uuid\n  tokenHash     String    @unique @map(\"token_hash\")\n  purpose       String\n  userId        String    @map(\"user_id\") @db.Uuid\n  sessionId     String?   @map(\"session_id\") @db.Uuid\n  tenantId      String?   @map(\"tenant_id\") @db.Uuid\n  membershipId  String?   @map(\"membership_id\") @db.Uuid\n  predecessorId String?   @unique @map(\"predecessor_id\") @db.Uuid\n  expiresAt     DateTime  @map(\"expires_at\")\n  consumedAt    DateTime? @map(\"consumed_at\")\n  revokedAt     DateTime? @map(\"revoked_at\")\n  createdAt     DateTime  @default(now()) @map(\"created_at\")\n  updatedAt     DateTime  @updatedAt @map(\"updated_at\")\n\n  user        User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  session     Session?    @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n  membership  Membership? @relation(fields: [tenantId, membershipId, userId], references: [tenantId, id, userId], onDelete: Restrict)\n  predecessor AuthToken?  @relation(\"RefreshRotation\", fields: [predecessorId], references: [id], onDelete: Restrict)\n  successor   AuthToken?  @relation(\"RefreshRotation\")\n\n  @@index([userId, purpose])\n  @@index([sessionId])\n  @@index([tenantId, membershipId])\n  @@index([purpose, expiresAt])\n  @@map(\"auth_tokens\")\n}\n",
